﻿<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Cloud Storage Alert</title>
    <link
        href="https://fonts.googleapis.com/css2?family=Inter:opsz,wght@14..32,400;14..32,500;14..32,600;14..32,700;14..32,800;14..32,900&display=swap"
        rel="stylesheet">
    <style>
        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background: #E0F2FE;
            font-family: 'Inter', -apple-system, sans-serif;
            -webkit-font-smoothing: antialiased;
            padding: 40px 16px;
        }

        .wrapper {
            max-width: 580px;
            margin: 0 auto;
        }

        /* HEADER */
        .header {
            background: #FFFFFF;
            border-radius: 12px 12px 0 0;
            padding: 20px 32px;
            border-bottom: 1px solid #E8EAED;
            display: table;
            width: 100%;
        }

        .header-left {
            display: table-cell;
            vertical-align: middle;
        }

        .header-right {
            display: table-cell;
            vertical-align: middle;
            text-align: right;
        }

        .logo-wrap {
            display: inline-block;
        }

        .logo-icon {
            display: inline-block;
            vertical-align: middle;
            margin-right: 8px;
        }

        .logo-name {
            display: inline-block;
            vertical-align: middle;
            font-size: 15px;
            font-weight: 700;
            color: #0F172A;
        }

        .header-date {
            font-size: 12px;
            color: #64748B;
            font-weight: 500;
        }

        /* ALERT BANNER */
        .alert-banner {
            background: #EFF6FF;
            border-left: 4px solid #2563EB;
            padding: 14px 32px;
            display: table;
            width: 100%;
        }

        .alert-icon-cell {
            display: table-cell;
            vertical-align: middle;
            width: 28px;
        }

        .alert-text-cell {
            display: table-cell;
            vertical-align: middle;
        }

        .alert-text {
            font-size: 13px;
            font-weight: 600;
            color: #1E40AF;
            line-height: 1.4;
        }

        /* BODY */
        .body-card {
            background: #FFFFFF;
            padding: 32px 32px 0;
        }

        .body-title {
            font-size: 22px;
            font-weight: 800;
            color: #0F172A;
            line-height: 1.3;
            margin-bottom: 10px;
        }

        .body-desc {
            font-size: 14px;
            color: #475569;
            line-height: 1.65;
            margin-bottom: 28px;
        }

        .body-desc strong {
            color: #0F172A;
            font-weight: 600;
        }

        /* PLAN BOX */
        .plan-box {
            background: #F8FAFC;
            border: 1px solid #E2E8F0;
            border-radius: 10px;
            overflow: hidden;
            margin-bottom: 28px;
        }

        .plan-box-header {
            background: #F1F5F9;
            padding: 12px 20px;
            display: table;
            width: 100%;
            border-bottom: 1px solid #E2E8F0;
        }

        .plan-box-header-left {
            display: table-cell;
            vertical-align: middle;
        }

        .plan-box-header-right {
            display: table-cell;
            vertical-align: middle;
            text-align: right;
        }

        .plan-name {
            font-size: 13px;
            font-weight: 700;
            color: #0F172A;
        }

        .plan-devices {
            font-size: 12px;
            color: #475569;
            margin-top: 1px;
        }

        .plan-tag {
            display: inline-block;
            background: #ff2222;
            color: #fff;
            font-size: 11px;
            font-weight: 700;
            padding: 3px 9px;
            border-radius: 3px;
        }

        .plan-row {
            display: table;
            width: 100%;
            padding: 13px 20px;
            border-bottom: 1px solid #E2E8F0;
        }

        .plan-row:last-child {
            border-bottom: none;
        }

        .plan-row-label {
            display: table-cell;
            font-size: 13px;
            color: #475569;
            vertical-align: middle;
            font-weight: 500;
        }

        .plan-row-value {
            display: table-cell;
            font-size: 13px;
            color: #0F172A;
            vertical-align: middle;
            text-align: right;
            font-weight: 600;
        }

        .price-new {
            font-size: 18px;
            font-weight: 800;
            color: #0F172A;
        }

        .save-chip {
            display: inline-block;
            background: #2563EB;
            color: #fff;
            font-size: 11px;
            font-weight: 700;
            padding: 2px 7px;
            border-radius: 3px;
            margin-left: 6px;
            vertical-align: middle;
            position: relative;
            top: -1px;
        }

        /* CTA */
        .cta-wrap {
            padding: 0 0 32px;
        }

        .btn {
            display: block;
            background: #2563EB;
            color: #FFFFFF;
            text-decoration: none;
            padding: 15px;
            border-radius: 8px;
            font-size: 15px;
            font-weight: 700;
            text-align: center;
            width: 100%;
        }

        .cta-note {
            font-size: 12px;
            color: #94A3B8;
            margin-top: 10px;
            text-align: center;
            line-height: 1.5;
        }

        /* FOOTER NOTE */
        .footer-note {
            background: #F8FAFC;
            border-top: 1px solid #E2E8F0;
            padding: 20px 32px;
            border-radius: 0 0 12px 12px;
        }

        .footer-note p {
            font-size: 13px;
            color: #475569;
            line-height: 1.65;
        }

        .footer-note p+p {
            margin-top: 6px;
        }

        .footer-note strong {
            color: #0F172A;
            font-weight: 600;
        }

        /* UNSUB */
        .unsub {
            text-align: center;
            font-size: 11px;
            color: #94A3B8;
            padding: 18px 0 4px;
        }

        .unsub a {
            color: #94A3B8;
            text-decoration: underline;
        }

        @media only screen and (max-width: 480px) {
            .header {
                padding: 16px 20px;
            }

            .alert-banner {
                padding: 12px 20px;
            }

            .body-card {
                padding: 24px 20px 0;
            }

            .footer-note {
                padding: 18px 20px;
            }

            .btn {
                font-size: 14px;
            }

            .plan-box-header-left,
            .plan-box-header-right {
                display: block;
                width: 100%;
                text-align: left;
            }

            .plan-box-header-right {
                margin-top: 6px;
            }
        }
    </style>
</head>

<body>
    <div class="wrapper">

        <!-- HEADER -->
        <table class="header" width="100%" cellpadding="0" cellspacing="0" border="0">
            <tr>
                <td class="header-left">
